/* PickPack 1291 — prototype only. Independent implementation inspired by Horilla's published UI patterns. No API, auth, storage, or provider calls. */
(()=>{
'use strict';
const root=document.getElementById('root');
const PAGES={dashboard:{title:'Tổng quan',desc:'Tình hình vận hành Pick Pack 1291'},people:{title:'Nhân sự',desc:'Danh sách và hồ sơ nhân sự'},shifts:{title:'Ra / vào ca',desc:'Theo dõi quét ca và user làm việc'},labor:{title:'Công nhật',desc:'Tổng hợp công theo ngày và ca'},minutes:{title:'Biên bản',desc:'Quản lý và lưu trữ biên bản'},assets:{title:'Công cụ dụng cụ',desc:'Danh mục, tình trạng và cấp phát'},pda:{title:'Mượn / trả PDA',desc:'Theo dõi thiết bị và người đang sử dụng'}};
const SIDEBAR=[{name:'BẢNG ĐIỀU KHIỂN',items:[['dashboard','grid']]},{name:'QUẢN LÝ NHÂN SỰ',items:[['people','users'],['shifts','clock'],['labor','calendar']]},{name:'HỒ SƠ & THIẾT BỊ',items:[['minutes','file'],['assets','boxes'],['pda','device']]}];
const ICONS={grid:'▦',users:'♙',clock:'◷',calendar:'▦',file:'▤',boxes:'▣',device:'▯',search:'⌕',bell:'♧',settings:'⚙',menu:'☰',close:'×',sun:'☼',moon:'☾',plus:'+',external:'↗',chev:'›',filter:'≡',check:'✓',alert:'!',right:'→'};
// Completely synthetic, reproducible operational examples. No real employee or device records.
const STORAGE_KEY='pickpack1291_fake_records_v05';
const SESSION_KEY='pickpack1291_demo_session_v05';
function storageGet(key){try{return localStorage.getItem(key)}catch{return null}}
function storageSet(key,val){try{localStorage.setItem(key,val);return true}catch{return false}}
function storageRemove(key){try{localStorage.removeItem(key)}catch{}}
function demoSession(){return storageGet(SESSION_KEY)==='demo-admin-only'||(location.protocol==='file:'&&new URLSearchParams(location.search).get('demo')==='1')}
function seedRecords(){
 const family=['Nguyễn','Trần','Lê','Phạm','Hoàng','Vũ','Đặng','Bùi','Đỗ','Phan','Ngô','Hồ'];
 const middle=['Minh','Thị','Văn','Hồng','Quang','Thanh','Đức','Ngọc','Gia','Tuấn'];
 const given=['An','Bình','Châu','Dũng','Giang','Hà','Hải','Hạnh','Huy','Khánh','Lan','Linh','Long','Mai','Nam','Nhi','Phúc','Quân','Sơn','Trang','Vy','Yến'];
 const states=['Đang làm việc','Chờ vào ca','Nghỉ ca'];
 const people=Array.from({length:36},(_,i)=>({id:`DEMO-NV-${String(i+1).padStart(3,'0')}`,name:`${family[i%family.length]} ${middle[(i*3+2)%middle.length]} ${given[(i*5+3)%given.length]}`,team:['Pick','Pack','Auto Pack','Điều phối'][i%4],shift:i%3===0?'Ca 2':'Ca 1',user:`demo.user${String(i+1).padStart(3,'0')}`,state:states[i%3],email:`demo-nv${String(i+1).padStart(3,'0')}@example.invalid`,initial:`M${(i%9)+1}`}));
 const shifts=Array.from({length:42},(_,i)=>{const person=people[i%people.length],end=i%4===0;return {id:`DEMO-CA-${String(i+1).padStart(3,'0')}`,name:person.name,staff:person.id,date:`${String(14-Math.floor(i/8)).padStart(2,'0')}/11/2026`,shift:person.shift,checkin:i%5===0?'—':`0${5+(i%3)}:${String(28+i%31).padStart(2,'0')}`,checkout:end?'14:0'+(i%9):'—',user:person.user,state:end?'Đã ra ca':i%5===0?'Chờ vào ca':'Trong ca'};});
 const labor=Array.from({length:42},(_,i)=>{const person=people[(i*7)%people.length];return {id:`DEMO-CN-${String(i+1).padStart(3,'0')}`,name:person.name,date:`${String(14-Math.floor(i/9)).padStart(2,'0')}/11/2026`,shift:person.shift,work:person.team,hours:['8,0','8,5','9,0','0,0'][i%4],state:['Đã xác nhận','Tạm tính','Chưa chấm'][i%3]};});
 const issueTypes=['Bàn giao ca','Thiết bị','Tác nghiệp','An toàn','Kỷ luật'];
 const minutes=Array.from({length:30},(_,i)=>({id:`DEMO-BB-${String(i+1).padStart(3,'0')}`,name:`Biên bản ${issueTypes[i%issueTypes.length].toLowerCase()} — mẫu ${String(i+1).padStart(2,'0')}`,type:issueTypes[i%issueTypes.length],date:`${String(14-Math.floor(i/6)).padStart(2,'0')}/11/2026`,owner:people[(i*3)%people.length].name,state:['Chờ xác nhận','Đã lưu','Đã xác nhận'][i%3]}));
 const goods=['Máy quét mã vạch','Khay phân loại','Bộ sạc thiết bị','Xe đẩy hàng','Bút kiểm kho','Băng dính','Giỏ nhựa','Tem nhãn','Bộ đàm','Kéo an toàn','Găng tay','Bảng kê'];
 const assets=Array.from({length:30},(_,i)=>({id:`DEMO-CCDC-${String(i+1).padStart(3,'0')}`,name:`${goods[i%goods.length]} — lô ${Math.floor(i/goods.length)+1}`,type:i%3===0?'Thiết bị':'Dụng cụ',qty:2+(i*7%19),unit:['chiếc','cái','bộ'][i%3],holder:['Kho CCDC','Khu Pick','Khu Pack','Khu Auto'][i%4],state:['Sẵn sàng','Đang sử dụng','Cần kiểm tra'][i%3]}));
 // 30 borrowing/return history entries across exactly three distinct demo PDA devices.
 const pda=Array.from({length:30},(_,i)=>({id:`DEMO-MT-${String(i+1).padStart(3,'0')}`,name:`PDA-${String(i%3+1).padStart(2,'0')}`,holder:people[(i*2)%people.length].name,user:people[(i*2)%people.length].user,borrow:`0${5+(i%4)}:${String(20+i%37).padStart(2,'0')}`,return:i<2?'—':`1${4+i%3}:${String(10+i%39).padStart(2,'0')}`,state:i<2?'Đang mượn':'Đã trả'}));
 return {people,shifts,labor,minutes,assets,pda};
}
function readRecords(){try{const data=JSON.parse(storageGet(STORAGE_KEY)||'null');if(data&&Object.keys(seedRecords()).every(k=>Array.isArray(data[k])&&data[k].length<500))return data}catch{}return seedRecords()}
const store=readRecords();
function persist(){storageSet(STORAGE_KEY,JSON.stringify(store))}
function updateRecord(key,id,changes){const row=store[key]?.find(r=>r.id===id);if(!row)return false;Object.assign(row,changes);persist();return true}
const columns={
 people:[['name','Nhân sự'],['id','Mã NV'],['team','Bộ phận'],['shift','Ca'],['user','User làm việc'],['state','Trạng thái']],
 shifts:[['name','Nhân sự'],['date','Ngày'],['shift','Ca'],['checkin','Vào ca'],['checkout','Ra ca'],['user','User làm việc'],['state','Trạng thái']],
 labor:[['name','Nhân sự'],['date','Ngày'],['shift','Ca'],['work','Công việc'],['hours','Giờ công'],['state','Trạng thái']],
 minutes:[['name','Tên biên bản'],['id','Mã'],['type','Loại'],['date','Ngày'],['owner','Người lập'],['state','Trạng thái']],
 assets:[['name','Tên CCDC'],['id','Mã'],['type','Loại'],['qty','Số lượng'],['holder','Vị trí'],['state','Trạng thái']],
 pda:[['name','Thiết bị'],['holder','Người mượn'],['user','User làm việc'],['borrow','Giờ mượn'],['return','Giờ trả'],['state','Trạng thái']]
};
const state={view:'dashboard',theme:'light',search:'',filter:'all',layout:'table',drawer:'',modal:'',sidebar:false,notice:'',editId:'',selected:new Set(),loginError:'',loginVisible:false};
const escape=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const qs=new URLSearchParams(location.search);state.view=PAGES[qs.get('view')]?qs.get('view'):'dashboard';state.theme=qs.get('theme')==='dark'?'dark':'light';state.drawer=qs.get('record')||'';
const href=(view=state.view,record='',theme=state.theme)=>`app.html?view=${encodeURIComponent(view)}&theme=${theme}`+(record?`&record=${encodeURIComponent(record)}`:'')+(location.protocol==='file:'?'&demo=1':'');
const badge=(v)=>{const s=String(v);const type=/Chờ|Cần kiểm tra|Chưa/.test(s)?'warn':/Đã lưu|Đã xác nhận|Sẵn sàng|Đã ra/.test(s)?'neutral':/Trong ca|Đang|Tạm tính/.test(s)?'good':'neutral';return `<span class="status ${type}"><span class="status-dot"></span>${escape(s)}</span>`};
const avatar=(x,big=false)=>`<span class="person-avatar ${big?'big':''}" aria-hidden="true">${escape(x.initial || String(x.name||'A').slice(-2).toUpperCase())}</span>`;
function side(){return `<aside class="sidebar ${state.sidebar?'is-open':''}" aria-label="Điều hướng PickPack"><div class="side-top"><img class="brand-logo" src="assets/supra-mark.png" alt="The Supra"><div><strong>PickPack 1291</strong><small>QUẢN LÝ VẬN HÀNH</small></div><button class="mobile-hide" data-action="close-nav" aria-label="Đóng menu">×</button></div><div class="sidebar-scroll"><div class="location-chip"><span class="location-icon">⌂</span><div><strong>Kho 1291</strong><small>Kiểm thử nội bộ · dữ liệu giả</small></div><span class="caret">⌄</span></div>${SIDEBAR.map(group=>`<div class="side-group"><span class="group-title">${group.name}</span>${group.items.map(([view,icon])=>`<div class="side-link ${state.view===view?'selected':''}"><a class="nav-main" href="${href(view)}" data-nav="${view}" aria-current="${state.view===view?'page':'false'}" title="Chuột phải để mở tab mới"><span class="nav-icon">${ICONS[icon]}</span><span>${PAGES[view].title}</span></a></div>`).join('')}</div>`).join('')}</div><div class="side-bottom"><span class="online-dot"></span><div><strong>Admin Demo</strong><small>Toàn quyền dữ liệu mẫu</small></div><button class="side-logout" data-action="logout" title="Đăng xuất" aria-label="Đăng xuất">⇥</button></div></aside>`}
function top(){return `<header class="topbar"><div class="top-left"><button class="icon-button menu-button" data-action="toggle-nav" aria-label="Mở menu">☰</button><div class="breadcrumb">Hệ thống <span>›</span><strong>${PAGES[state.view].title}</strong></div></div><div class="top-right"><div class="top-search"><span>⌕</span><input id="global-search" type="search" placeholder="Tìm nhanh trong ${PAGES[state.view].title.toLowerCase()}..." value="${escape(state.search)}" aria-label="Tìm nhanh"></div><span class="top-divider"></span><button class="icon-button" data-action="theme" title="Chuyển sáng/tối" aria-label="Chuyển chế độ màu">${state.theme==='light'?'☾':'☼'}</button><button class="icon-button notif" data-action="notifications" title="Thông báo mẫu" aria-label="Thông báo mẫu">♧<i></i></button><div class="top-profile">${avatar({initial:'AD'})}<div><strong>Admin Demo</strong><small>Chỉ review giao diện</small></div><span class="caret">⌄</span></div></div></header>`}
function pageHead(action='',other=''){return `<div class="page-header"><div><div class="eyebrow">PICK PACK 1291 / <span>${PAGES[state.view].title.toUpperCase()}</span></div><h1>${PAGES[state.view].title}</h1><p>${PAGES[state.view].desc}. <b>Toàn bộ dữ liệu hiển thị là giả lập.</b></p></div><div class="header-actions">${other}${action}</div></div>`}
function stat(label,value,small,accent='blue',icon='▦'){return `<div class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon ${accent}">${icon}</span></div><div class="metric-number">${value}</div><div class="metric-foot">${small}</div></div>`}
function activity(){return `<section class="panel activity-panel"><div class="panel-title"><div><h2>Hoạt động gần đây</h2><p>Dòng thời gian thao tác giả lập</p></div><span class="muted">Hôm nay</span></div><div class="timeline">${[['09:12','Cấp phát PDA mẫu 02','Thiết bị · Nhân sự mẫu B'],['08:36','Tạo biên bản bàn giao ca','Hồ sơ · Đang chờ xác nhận'],['06:12','Cập nhật user làm việc','Nhân sự · pp.demo01'],['05:31','Ghi nhận nhân sự vào ca','Ra / vào ca · Ca 1']].map(([time,name,sub],i)=>`<div class="timeline-row"><span class="timeline-indicator ${i===0?'current':''}"></span><div><strong>${name}</strong><small>${sub}</small></div><time>${time}</time></div>`).join('')}</div></section>`}
function workload(){const points=[38,55,43,73,62,86,68],labs=['05h','07h','09h','11h','13h','15h','17h'];return `<section class="panel chart-panel"><div class="panel-title"><div><h2>Minh họa phân bổ nhân sự</h2><p>Ví dụ hiển thị theo khung giờ, không phải dữ liệu thực</p></div><span class="legend"><i></i>Đang làm việc</span></div><div class="chart-area"><div class="chart-lines"><span>100%</span><span>75%</span><span>50%</span><span>25%</span></div><div class="chart-bars">${points.map((x,i)=>`<div class="chart-col"><div class="bar-wrap"><div class="bar" style="height:${x}%"><span>${x}%</span></div></div><small>${labs[i]}</small></div>`).join('')}</div></div></section>`}
function attention(){return `<section class="panel alert-panel"><div class="panel-title"><div><h2>Cần kiểm tra</h2><p>Các mục minh họa cần thao tác</p></div><span class="bubble">03</span></div><div class="alert-list"><a href="${href('minutes')}" class="alert-row"><span class="alert-icon amber">!</span><span><strong>Biên bản chờ xác nhận</strong><small>1 bản ghi mẫu</small></span><span>›</span></a><a href="${href('assets')}" class="alert-row"><span class="alert-icon amber">!</span><span><strong>CCDC cần kiểm tra</strong><small>1 thiết bị minh họa</small></span><span>›</span></a><a href="${href('shifts')}" class="alert-row"><span class="alert-icon blue">◷</span><span><strong>Nhân sự chờ vào ca</strong><small>1 bản ghi mẫu</small></span><span>›</span></a></div></section>`}
function dashboard(){return `<div class="page-content">${pageHead(`<button class="btn primary" data-action="add">+ Tạo ghi nhận mẫu</button>`)}<div class="demo-note"><span class="note-icon">i</span><span><strong>CHẾ ĐỘ XEM TRƯỚC:</strong> đây là giao diện được xây dựng theo mô hình Horilla; số liệu, người và thiết bị bên dưới hoàn toàn giả lập, đăng nhập demo chạy trong trình duyệt, không có xác thực server hoặc kết nối API.</span></div><div class="metrics">${stat('Nhân sự mẫu',String(store.people.length).padStart(2,'0'),'Danh sách hồ sơ giả lập','blue','♙')}${stat('Đang trong ca',String(store.shifts.filter(r=>r.state==='Trong ca').length).padStart(2,'0'),'Lịch sử quét ca mẫu','green','◷')}${stat('PDA đang mượn',String(new Set(store.pda.filter(r=>r.state==='Đang mượn').map(r=>r.name)).size).padStart(2,'0')+' / 03','Ba mã thiết bị thử nghiệm','purple','▯')}${stat('Biên bản chờ duyệt',String(store.minutes.filter(r=>r.state==='Chờ xác nhận').length).padStart(2,'0'),'Danh sách minh họa','orange','▤')}</div><div class="two-col">${workload()}${attention()}</div><div class="two-col lower">${activity()}<section class="panel shortcut-panel"><div class="panel-title"><div><h2>Truy cập nhanh</h2><p>Những chức năng dùng thường xuyên</p></div></div><div class="shortcut-grid">${[['people','♙','Tra cứu nhân sự'],['shifts','◷','Ghi nhận ra/vào'],['labor','▦','Bảng công nhật'],['minutes','▤','Biên bản'],['assets','▣','Kho CCDC'],['pda','▯','Mượn / trả PDA']].map(([view,ic,title])=>`<a href="${href(view)}" class="shortcut"><span>${ic}</span><strong>${title}</strong><small>→</small></a>`).join('')}</div></section></div></div>`}
function tableCell(row,key,view){if(key==='name')return `<div class="cell-name">${view==='people'?avatar(row):''}<div><strong>${escape(row.name)}</strong>${view==='people'?`<small>${escape(row.email)}</small>`:''}</div></div>`;if(key==='state')return badge(row[key]);if(key==='id')return `<span class="mono">${escape(row[key])}</span>`;return escape(row[key])}
function filtered(){const set=store[state.view]||[];let rows=set.filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(state.search.toLowerCase())));if(state.filter!=='all')rows=rows.filter(x=>String(x.state)===state.filter);return rows}
function controls(){let statuses=[...new Set((store[state.view]||[]).map(x=>x.state))];return `<div class="table-controls"><div class="table-control-left"><span class="listing-icon">≡</span><span class="records-label">Danh sách <b>${store[state.view].length}</b></span><span class="separator"></span><label class="filter-label">Trạng thái <select id="status-filter" aria-label="Lọc theo trạng thái"><option value="all">Tất cả</option>${statuses.map(x=>`<option value="${escape(x)}" ${state.filter===x?'selected':''}>${escape(x)}</option>`).join('')}</select></label></div><div class="table-control-right"><button class="btn ghost tiny" data-action="export" title="Xuất bản ghi đang lọc">↓ CSV</button><button class="btn ghost tiny" data-action="reset" title="Đặt lại dữ liệu mô phỏng">↺ Đặt lại</button><button class="btn danger tiny" data-action="bulk-delete" ${state.selected.size?'':'disabled'}>Xóa đã chọn (${state.selected.size})</button><button class="btn icon-label ${state.layout==='table'?'active':''}" data-action="layout-table" aria-label="Dạng bảng">☷ <span>Bảng</span></button><button class="btn icon-label ${state.layout==='cards'?'active':''}" data-action="layout-cards" aria-label="Dạng thẻ">▦ <span>Thẻ</span></button></div></div>`}
function recordActions(r){return `<span class="row-actions"><button class="row-open" data-record="${escape(r.id)}" title="Xem chi tiết">◉</button><button class="row-open" data-edit="${escape(r.id)}" title="Sửa bản ghi">✎</button><button class="row-open danger-text" data-delete="${escape(r.id)}" title="Xóa bản ghi">×</button></span>`}
function table(){const cols=columns[state.view],rows=filtered();return `<section class="panel table-panel">${controls()}${rows.length?state.layout==='cards'?`<div class="record-cards">${rows.map(r=>`<div class="record-card"><div><strong>${escape(r.name)}</strong>${badge(r.state)}</div><dl>${cols.slice(1,-1).map(([k,label])=>`<div><dt>${label}</dt><dd>${escape(r[k])}</dd></div>`).join('')}</dl><div class="card-actions"><a class="inline-link" href="${href(state.view,r.id)}" title="Chuột phải để mở trong tab mới">Chi tiết</a>${recordActions(r)}</div></div>`).join('')}</div>`:`<div class="table-scroll"><table><thead><tr><th><input type="checkbox" id="select-all" aria-label="Chọn tất cả bản ghi đang hiển thị" ${rows.every(x=>state.selected.has(x.id))?'checked':''}></th>${cols.map(([,lab])=>`<th>${lab}</th>`).join('')}<th>Thao tác</th></tr></thead><tbody>${rows.map(r=>`<tr><td><input type="checkbox" data-select="${escape(r.id)}" aria-label="Chọn ${escape(r.id)}" ${state.selected.has(r.id)?'checked':''}></td>${cols.map(([k])=>`<td>${k==='name'?`<a class="inline-link cell-record-link" href="${href(state.view,r.id)}" title="Chuột phải để mở tab mới">${tableCell(r,k,state.view)}</a>`:tableCell(r,k,state.view)}</td>`).join('')}<td>${recordActions(r)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>Không tìm thấy bản ghi phù hợp</strong><span>Thử điều chỉnh bộ lọc hoặc từ khóa</span></div>`}<div class="table-footer"><span>Hiển thị ${rows.length} / ${store[state.view].length} bản ghi giả lập · mở tab khác bằng chuột phải trên liên kết</span><span>Trang 1 / 1</span></div></section>`}
function modulePage(){let n=(store[state.view]||[]).length;let call=state.view==='shifts'?'Ghi nhận quét mẫu':state.view==='pda'?'Mượn / trả mẫu':state.view==='people'?'Thêm nhân sự mẫu':state.view==='minutes'?'Tạo biên bản mẫu':state.view==='assets'?'Thêm CCDC mẫu':'Thêm công nhật mẫu';return `<div class="page-content">${pageHead(`<button class="btn primary" data-action="add">+ ${call}</button>`)}<div class="module-summary">${stat('Tổng bản ghi',String(n).padStart(2,'0'),'Giả lập trong trình duyệt','blue','≡')}${stat('Đang xử lý',String((store[state.view]||[]).filter(r=>/Chờ|Đang|Trong ca|Tạm tính/.test(r.state)).length).padStart(2,'0'),'Trạng thái minh họa','orange','◷')}${stat('Mục được xem','01','Tab hiện tại','green','▦')}</div>${table()}</div>`}
function quickLabel(){return state.view==='pda'?'Mượn / trả':state.view==='shifts'?'Quét ca':state.view==='labor'?'Xác nhận công':state.view==='minutes'?'Duyệt biên bản':'Đổi trạng thái'}
function drawer(){if(!state.drawer)return '';const row=store[state.view]?.find(x=>x.id===state.drawer);if(!row)return '';return `<div class="drawer-shade" data-action="close-drawer"></div><aside class="detail-drawer" role="dialog" aria-modal="true" aria-label="Chi tiết ${escape(row.id)}"><div class="detail-head"><div><small>HỒ SƠ GIẢ LẬP</small><h2>${escape(row.name)}</h2></div><button class="icon-button" data-action="close-drawer" aria-label="Đóng chi tiết">×</button></div><div class="detail-content"><div class="detail-hero"><span class="detail-icon">${state.view==='people'?'♙':state.view==='pda'?'▯':'▤'}</span><div><strong>${escape(row.name)}</strong><small>${escape(row.id)}</small></div></div>${badge(row.state)}<div class="detail-fields">${(columns[state.view]||[]).slice(1).map(([k,label])=>`<div><span>${label}</span><b>${escape(row[k])}</b></div>`).join('')}</div><div class="detail-tip">Có thể sửa, xóa hoặc đổi trạng thái bản ghi giả lập. Dữ liệu lưu cục bộ trong trình duyệt, không gửi lên server.</div><div class="drawer-actions"><button class="btn primary" data-edit="${escape(row.id)}">✎ Chỉnh sửa</button><button class="btn ghost" data-quick="${escape(row.id)}">${quickLabel()}</button><button class="btn danger" data-delete="${escape(row.id)}">Xóa</button></div></div></aside>`}
const FIELD_OPTIONS={team:['Pick','Pack','Auto Pack','Điều phối'],shift:['Ca 1','Ca 2'],state:['Đang làm việc','Chờ vào ca','Nghỉ ca','Trong ca','Đã ra ca','Tạm tính','Đã xác nhận','Chưa chấm','Chờ xác nhận','Đã lưu','Sẵn sàng','Đang sử dụng','Cần kiểm tra','Đang mượn','Đã trả'],type:['Bàn giao ca','Thiết bị','Tác nghiệp','An toàn','Kỷ luật'],work:['Pick','Pack','Auto Pack','Điều phối']};
function fieldInput(key,label,value){if(key==='id')return '';const opts=FIELD_OPTIONS[key];const v=String(value??'');if(opts)return `<label>${escape(label)}<select name="${key}" required><option value="">— Chọn —</option>${[...new Set([...opts,v])].filter(Boolean).map(x=>`<option value="${escape(x)}" ${x===v?'selected':''}>${escape(x)}</option>`).join('')}</select></label>`;if(key==='qty')return `<label>${escape(label)}<input type="number" min="0" max="99999" name="${key}" value="${escape(v)}" required></label>`;return `<label>${escape(label)}<input name="${key}" maxlength="120" value="${escape(v)}" placeholder="${escape(label)}" ${key==='name'?'minlength="2" required':''} autocomplete="off"></label>`}
function modal(){if(!state.modal)return '';const key=state.view==='dashboard'?'minutes':state.view;const existing=store[key]?.find(r=>r.id===state.editId);const editing=state.modal==='edit'&&!!existing;const title=editing?`Sửa ${PAGES[key].title.toLowerCase()}`:`Thêm ${PAGES[key].title.toLowerCase()}`;return `<div class="modal-overlay" data-action="close-modal"><section class="modal modal-wide" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><span>QUẢN TRỊ DỮ LIỆU MẪU</span><h2 id="modal-title">${title}</h2></div><button class="icon-button" data-action="close-modal" aria-label="Đóng cửa sổ">×</button></div><form id="record-form"><p>Thử nghiệm nghiệp vụ tại trình duyệt. Tuyệt đối không nhập dữ liệu nhân sự hoặc thiết bị thật.</p><div class="form-grid">${columns[key].filter(([k])=>k!=='id').map(([k,l])=>fieldInput(k,l,editing?existing[k]:k==='state'?'Chờ xác nhận':'')).join('')}</div><div class="modal-actions"><button type="button" class="btn ghost" data-action="close-modal">Hủy</button><button class="btn primary" type="submit">${editing?'Lưu chỉnh sửa':'Tạo bản ghi'}</button></div></form></section></div>`}
function toast(){return state.notice?`<div class="toast" role="status">${escape(state.notice)}<button data-action="clear-notice" aria-label="Đóng thông báo">×</button></div>`:''}
function render(){document.documentElement.setAttribute('data-theme',state.theme);if(document.body.dataset.screen==='login'){renderLogin();return}if(!demoSession()){root.innerHTML=`<main class="auth-required"><img src="assets/supra-mark.png" alt="The Supra"><h2>Cần đăng nhập bản mẫu</h2><p>Đăng nhập Admin Demo trước khi sử dụng giao diện và các tab nghiệp vụ.</p><a class="btn primary" href="index.html">Về trang đăng nhập</a></main>`;return}root.innerHTML=`${side()}<div class="screen-shade ${state.sidebar?'show':''}" data-action="close-nav"></div><div class="app-main">${top()}${state.view==='dashboard'?dashboard():modulePage()}<footer class="site-footer">PickPack 1291 · UI prototype v0.5 · Quản trị dữ liệu giả · Không có backend</footer></div>${drawer()}${modal()}${toast()}`}
function renderLogin(){root.innerHTML=`<main class="login-screen"><div class="login-panel"><div class="login-left"><div class="login-brand"><img class="brand-logo" src="assets/supra-mark.png" alt="The Supra"><span>PickPack 1291</span></div><div class="login-art"><div class="art-greeting">QUẢN LÝ VẬN HÀNH</div><h1>Một nơi cho mọi hoạt động Pick & Pack.</h1><p>Trải nghiệm thiết kế quản trị nhân sự và thiết bị cho kho 1291.</p><div class="art-metrics"><div><strong>07</strong><span>Phân hệ</span></div><div><strong>03</strong><span>Thiết bị PDA mã mẫu</span></div><div><strong>05</strong><span>Phiên Web mục tiêu*</span></div></div></div><small>* Chỉ là mục tiêu hệ thống sau này.</small></div><div class="login-right"><span class="login-kicker">ĐĂNG NHẬP THỬ NGHIỆM</span><h2>Đăng nhập hệ thống</h2><p>Đây là giao diện đăng nhập mô phỏng cho Admin, <b>không phải xác thực người dùng thật</b>.</p><form id="login-form" autocomplete="off" class="login-form"><label>Tên đăng nhập<input id="demo-user" name="username" value="" placeholder="Nhập tên đăng nhập" autocomplete="off" required></label><label>Mật khẩu<div class="password-wrap"><input id="demo-password" name="password" type="${state.loginVisible?'text':'password'}" placeholder="Nhập mật khẩu" autocomplete="off" required><button type="button" class="password-toggle" data-action="show-password" aria-label="${state.loginVisible?'Ẩn':'Hiện'} mật khẩu">${state.loginVisible?'Ẩn':'Hiện'}</button></div></label>${state.loginError?`<div class="login-error" role="alert">${escape(state.loginError)}</div>`:''}<button class="btn primary login-submit" type="submit">Đăng nhập <span>→</span></button></form><div class="demo-credentials"><span>THÔNG TIN KIỂM THỬ</span><strong>Username: admin &nbsp; · &nbsp; Password: admin</strong></div><div class="login-caution">Đăng nhập được kiểm tra trực tiếp bằng JavaScript trên thiết bị. Không bảo vệ dữ liệu, không liên quan tài khoản Inventory. Không được dùng bản này trên môi trường Production.</div><div class="login-links"><button data-action="theme" class="text-button">${state.theme==='dark'?'☼ Sáng':'☾ Tối'}</button></div></div></div></main>`}
function safeHistory(method,url){try{history[method](null,'',url)}catch{ /* Browser file:// history restrictions do not block UI. */ }}
function closeStuff(){state.sidebar=false;state.modal='';state.drawer='';state.editId=''}
function setView(view){state.view=view;state.search='';state.filter='all';state.drawer='';state.sidebar=false;state.selected.clear();safeHistory('pushState',href(view));render();window.scrollTo(0,0)}
function saveForm(form){const key=state.view==='dashboard'?'minutes':state.view;const fd=new FormData(form);const changes={};for(const [k] of columns[key]){if(k==='id')continue;const value=String(fd.get(k)??'').trim();changes[k]=k==='qty'?Number(value):value||'—'}if(String(changes.name).trim().length<2){state.notice='Tên bản ghi cần từ 2 ký tự';render();return}if(state.modal==='edit'&&state.editId){updateRecord(key,state.editId,changes);state.notice='Đã cập nhật bản ghi mô phỏng'}else{const id=`DEMO-${key.toUpperCase()}-${Date.now().toString(36).toUpperCase()}`;store[key].unshift({id,...changes});persist();state.notice='Đã tạo bản ghi mô phỏng'}state.modal='';state.editId='';state.search='';state.filter='all';render()}
function deleteIds(ids){const key=state.view;const matches=store[key].filter(r=>ids.includes(r.id));if(!matches.length)return;if(!window.confirm(`Xóa ${matches.length} bản ghi giả lập khỏi ${PAGES[key].title}?`))return;store[key]=store[key].filter(r=>!ids.includes(r.id));persist();state.selected.clear();state.drawer='';safeHistory('replaceState',href());state.notice=`Đã xóa ${matches.length} bản ghi mô phỏng`;render()}
function quickChange(id){const key=state.view;const row=store[key]?.find(x=>x.id===id);if(!row)return;let c={};if(key==='shifts'){const entered=row.state==='Trong ca';c={state:entered?'Đã ra ca':'Trong ca',checkin:entered?row.checkin:'05:35',checkout:entered?'14:05':'—'}}else if(key==='pda'){const borrowed=row.state==='Đang mượn';c={state:borrowed?'Đã trả':'Đang mượn',return:borrowed?'14:05':'—'}}else if(key==='minutes')c={state:'Đã xác nhận'};else if(key==='labor')c={state:'Đã xác nhận'};else if(key==='people')c={state:row.state==='Đang làm việc'?'Nghỉ ca':'Đang làm việc'};else if(key==='assets')c={state:row.state==='Sẵn sàng'?'Đang sử dụng':'Sẵn sàng'};updateRecord(key,id,c);state.notice=`Đã thay đổi trạng thái ${row.id} (chỉ dữ liệu mẫu)`;render()}
function exportCSV(){const rows=filtered(),fields=columns[state.view];const quote=s=>'"'+String(s??'').replaceAll('"','""')+'"';const csv='\ufeff'+[fields.map(([,label])=>quote(label)).join(','),...rows.map(r=>fields.map(([k])=>quote(r[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`pickpack-demo-${state.view}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);state.notice=`Xuất ${rows.length} bản ghi giả lập`;render()}
root.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();const fd=new FormData(e.target);const ok=String(fd.get('username')||'').trim()==='admin'&&String(fd.get('password')||'')==='admin';if(!ok){state.loginError='Sai tên đăng nhập hoặc mật khẩu mẫu';render();return}storageSet(SESSION_KEY,'demo-admin-only');state.loginError='';location.href=href('dashboard');return}if(e.target.id==='record-form'){e.preventDefault();saveForm(e.target)}});
root.addEventListener('click',e=>{
 const nav=e.target.closest('a[data-nav]');if(nav){if(e.button===0&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey){e.preventDefault();setView(nav.dataset.nav)}return}
 const record=e.target.closest('[data-record]');if(record){state.drawer=record.dataset.record;safeHistory('replaceState',href(state.view,state.drawer));render();return}
 const edit=e.target.closest('[data-edit]');if(edit){state.editId=edit.dataset.edit;state.modal='edit';render();return}
 const del=e.target.closest('[data-delete]');if(del){deleteIds([del.dataset.delete]);return}
 const quick=e.target.closest('[data-quick]');if(quick){quickChange(quick.dataset.quick);return}
 const btn=e.target.closest('[data-action]');if(!btn)return;
 const act=btn.dataset.action;if(act==='close-modal'&&btn.classList.contains('modal-overlay')&&e.target.closest('.modal'))return;
 switch(act){case'toggle-nav':state.sidebar=!state.sidebar;break;case'close-nav':state.sidebar=false;break;
 case'theme':state.theme=state.theme==='light'?'dark':'light';safeHistory('replaceState',document.body.dataset.screen==='app'?href(state.view,state.drawer):'index.html?theme='+state.theme);break;
 case'add':state.editId='';state.modal='new';break;case'close-modal':state.modal='';state.editId='';break;case'close-drawer':state.drawer='';safeHistory('replaceState',href());break;
 case'notifications':state.notice='Thông báo mô phỏng: không có dữ liệu server';break;
 case'layout-table':state.layout='table';break;case'layout-cards':state.layout='cards';break;case'clear-notice':state.notice='';break;
 case'show-password':{const form=root.querySelector('#login-form');const username=form?.querySelector('#demo-user')?.value||'';const password=form?.querySelector('#demo-password')?.value||'';state.loginVisible=!state.loginVisible;render();root.querySelector('#demo-user').value=username;root.querySelector('#demo-password').value=password;return}
 case'logout':storageRemove(SESSION_KEY);location.href='index.html';return;
 case'bulk-delete':deleteIds([...state.selected]);return;
 case'reset':if(window.confirm('Khôi phục toàn bộ dữ liệu giả lập gốc?')){Object.assign(store,seedRecords());persist();state.selected.clear();state.drawer='';state.notice='Đã khôi phục dữ liệu mẫu ban đầu';}break;
 case'export':exportCSV();return;
 }
 render();
});
root.addEventListener('input',e=>{if(e.target.id==='global-search'){const input=e.target;state.search=input.value;const pos=input.selectionStart;render();const newInput=root.querySelector('#global-search');if(newInput){newInput.focus();newInput.setSelectionRange(pos,pos)}}});
root.addEventListener('change',e=>{if(e.target.id==='status-filter'){state.filter=e.target.value;state.selected.clear();render();return}if(e.target.id==='select-all'){const ids=filtered().map(x=>x.id);if(e.target.checked)ids.forEach(id=>state.selected.add(id));else ids.forEach(id=>state.selected.delete(id));render();return}if(e.target.matches('[data-select]')){if(e.target.checked)state.selected.add(e.target.dataset.select);else state.selected.delete(e.target.dataset.select);render()}});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){const fresh=readRecords();for(const key of Object.keys(store))store[key]=fresh[key];state.notice='Dữ liệu mẫu đã thay đổi từ tab khác';render()}if(e.key===SESSION_KEY)render()});
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);state.view=PAGES[p.get('view')]?p.get('view'):'dashboard';state.theme=p.get('theme')==='dark'?'dark':'light';state.drawer=p.get('record')||'';state.search='';state.filter='all';state.selected.clear();render()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeStuff();render()}});
render();
})();
